-- Generated from src/notebooks/configs/dentroIlPcConfig.js. Safe to apply more than once.
insert into public.guided_notebooks (slug, description, node_id, pending_node_slug, config)
select 'dentro-il-pc', 'Esplora in modo guidato come software e sistema operativo usano kernel, driver e componenti hardware come CPU, RAM e SSD, distinguendo il percorso dei dati da quello dell''alimentazione.', n.id,
  case when n.id is null then 'dentro-il-pc' else null end,
  convert_from(decode('', 'base64'), 'UTF8')::jsonb
from (select 1) seed left join public.nodes n on n.slug = 'dentro-il-pc'
on conflict (slug) do nothing;
